  T.s13 = V(SAYN + '<p><i>deploy to</i> a cluster (не <i>on</i>, хоча й <i>on</i> трапляється). Помилка-мішень: <i>three new softwares</i>.</p>' +
    tr('Розмовний приклад: I installed three new apps and one piece of software for my camera. — Я встановив три нові застосунки й одну програму для фотоапарата.'));
  T.t4 = V(ul([
    'technique — прийом, спосіб виконання; technology — технологія як галузь або сукупність засобів. Приклад: Дистиляція — це прийом; периферійні обчислення — технологія.',
    'data / information в цьому значенні незлічувані: ніколи informations. Data допускає однинне й множинне узгодження; головне — послідовність у межах тексту. Приклад: Дані зашумлені. Інформацію зберігають у реєстрі.'
  ]));
  T.e25_6 = MC(0, 'a <b>technique</b> for shrinking a model', tr('Дистиляція — добре задокументований прийом зменшення моделі.'));
  T.s8 = V(SAYN + '<p>Пастка вимови: <i>technique</i> /tekˈniːk/ — наголос на другому складі.</p>' +
    tr('Розмовний приклад: For me, cooking is a hobby, not a chore. — Для мене куховарство — це хобі, а не обов’язок.'));

  /* ---------- 2.4 · vocabulary ---------- */
  T.e24_3 = MC(1, '✅ We have <b>the ability to run</b> / We <b>can run</b> the model in the browser.',
    tr('Ми маємо змогу запускати модель у браузері.') + '<p><b>Джерело:</b> калька «маємо можливість». Приймається <i>the opportunity to run</i>.</p>');
  T.e24_4 = MC(1, '✅ Serverless inference is a <b>very topical (current, hot)</b> topic in backend development.',
    tr('Безсерверне висновування — дуже актуальна тема в бекенд-розробці.') + '<p><b>Джерело:</b> міжмовний омонім «актуальний». Природно: <i>a hot topic</i>, <i>very relevant</i>.</p>');
  T.e24_10 = G('information is', ['information is'], '✅ The <b>information is</b> stored in the model registry.',
    tr('Інформацію зберігають у реєстрі моделей.') + '<p><b>Джерело:</b> українське «відомості» (множина). Два виправлення: іменник і дієслово. Приймається <i>data is / data are</i>, але тоді зміниться зміст.</p>');
  T.e24_5 = MC(1, '✅ Our team <b>implemented (built)</b> the caching layer last sprint.',
    tr('Минулого спринту наша команда реалізувала рівень кешування.') + '<p><b>Джерело:</b> «реалізувати» ≠ <i>realize</i>.</p>');
  T.e24_9 = MC(0, '✅ We shipped two new <b>services / applications / pieces of software</b> this quarter.',
    tr('Цього кварталу ми випустили дві нові програми (два нові сервіси).') + '<p><b>Джерело:</b> «софти»; <i>software</i> незлічуване.</p>');

  /* ---------- Reading ---------- */
